        internal static readonly System.Collections.Generic.Dictionary<string, string[]> GunTexts =
            new System.Collections.Generic.Dictionary<string, string[]>
        {
            { "gse_w001", new[] { "栓动式 7.62 毫米精确步枪。沙色金属底盘配长开孔护木，方形弹匣位于握把前方，骨架枪托装有可调贴腮板，粗枪管前端带大型制退器。", "A bolt-action 7.62 mm precision rifle. A tan metal chassis has a long perforated handguard, a square magazine ahead of the grip, a skeleton stock with an adjustable cheekpiece, and a heavy barrel ending in a large muzzle brake." } },
            { "gse_w002", new[] { "滚柱延迟反冲的 7.62 毫米战斗步枪。钢板冲压机匣又长又直，拉机柄位于护木左上方的长管内，枪托和护木是塑料，枪口带消焰器。", "A roller-delayed blowback 7.62 mm battle rifle. The stamped-steel receiver is long and straight, the charging handle sits in a tube above the handguard on the left, the stock and handguard are plastic, and the muzzle carries a flash hider." } },
            { "gse_w003", new[] { "击针击发的 10 毫米半自动手枪。低矮钢制套筒前后刻有斜向防滑槽，聚合物握把后缘高高伸出，扳机护圈方正，套筒座前端带短导轨。", "A striker-fired 10 mm semi-automatic pistol. Diagonal serrations mark both ends of the low steel slide, the polymer grip rises into a high rear extension, and a square trigger guard sits behind a short frame rail." } },
            { "gse_w004", new[] { "击针击发的 10 毫米轻型手枪。修长套筒上缘有连续斜面，聚合物握把表面覆盖细密颗粒，扳机带联动保险片，枪身前部设有附件导轨。", "A light striker-fired 10 mm pistol. The long slide has bevelled upper edges, fine stippling covers the polymer grip, a safety blade sits in the trigger, and an accessory rail runs beneath the front of the frame." } },
            { "gse_w005", new[] { ".45 口径自由枪机冲锋枪。铣削钢机匣配胡桃木枪托和前握把，枪管带散热片，枪口有防跳器，弹鼓或长弹匣插在机匣下方。", "A blowback .45 submachine gun. A milled steel receiver with a walnut stock and vertical foregrip, a finned barrel with a muzzle compensator, and a drum or stick magazine below." } },
            { "gse_w007", new[] { "栓动式 7.62 毫米狙击步枪。灰色铝合金上机匣与长护木连为一体，粗枪管外露，侧折骨架枪托带独立贴腮板，枪机柄位于宽大的抛壳口后方。", "A bolt-action 7.62 mm sniper rifle. The grey aluminium upper and long handguard form one piece, the heavy barrel remains exposed, a folding skeleton stock carries a separate cheekpiece, and the bolt handle sits behind a broad ejection port." } },
            { "gse_w008", new[] { "双活塞导气的 12 号半自动霰弹枪。黑色机匣顶部带短导轨，聚合物护木包住枪管下方，独立手枪式握把连接固定枪托，管式弹仓与枪管平行。", "A twin-piston gas-operated 12-gauge semi-automatic shotgun. A short rail tops the black receiver, a polymer forend encloses the underside of the barrel, and a pistol grip joins a fixed stock behind a parallel tubular magazine." } },
            { "gse_w009", new[] { "12 号泵动霰弹枪。黑色聚合物枪身搭配长枪管，枪托侧面嵌有斜向缓冲结构，宽护木带斜纹，枪管上方的通风瞄准肋一直延伸到准星。", "A 12-gauge pump-action shotgun. A black polymer body meets a long barrel, diagonal cushioning elements mark the stock sides, the broad forend has slanted grooves, and a ventilated sighting rib runs forward to the front sight." } },
            { "gse_w010", new[] { "导气式 12 号半自动霰弹枪。短机匣顶部设导轨与环形后照门，拉机柄圆头较大，聚合物护木表面粗糙，固定枪托通过弯曲握把过渡到枪身。", "A gas-operated 12-gauge semi-automatic shotgun. The short receiver carries a rail and aperture rear sight, the charging handle has a large rounded head, and a textured polymer forend pairs with a fixed stock and curved grip." } },
            { "gse_w011", new[] { "枪管短后坐、卡铁闭锁的 10 毫米半自动手枪。开放式套筒露出枪管上半部，铝合金套筒座搭配双排弹匣，外露击锤与套筒侧面的保险清晰可见。", "A short-recoil, locking-block 10 mm semi-automatic pistol. The open-top slide exposes the upper barrel, an aluminium frame holds a double-stack magazine, and the external hammer and slide-mounted safety are plainly visible." } },
            { "gse_w012", new[] { "短行程活塞导气的 5.56 毫米步枪。沙色聚合物机匣轮廓厚实，两侧各设抛壳口，短护木带有散热孔，折叠枪托与机匣颜色一致。", "A short-stroke gas-piston 5.56 mm rifle. The bulky tan polymer receiver has an ejection port on each side, a short vented handguard and a matching folding stock." } },
            { "gse_w013", new[] { "自由枪机的 10 毫米卡宾枪。圆润聚合物外壳把枪托、握把和护圈连成整体，大拇指孔位于握把后方，弹匣藏在握把内，细长枪管从前端伸出。", "A blowback 10 mm carbine. A rounded polymer shell joins the stock, grip and guard, with a large thumbhole behind the grip, a magazine inside it, and a slender barrel projecting from the front." } },
            { "gse_w014", new[] { "上下双管的 12 号竞技霰弹枪。长枪管顶部有高通风瞄准肋，银色机匣接深色木枪托，宽护木沿下管延伸，握把弧度明显，整体面向飞碟射击。", "A 12-gauge over-under competition shotgun. A high ventilated rib tops the long barrels, the silver receiver meets a dark wooden stock, a broad forend follows the lower barrel, and the curved grip completes a clay-target layout." } },
            { "gse_w015", new[] { "闭膛待击、自由枪机的 10 毫米冲锋枪。聚合物枪身短而紧凑，顶部是整根导轨，枪托可以向右折叠，左右两侧都能操作。", "A closed-bolt, blowback 10 mm submachine gun. The polymer body is short and compact with a full-length top rail, the stock folds to the right, and the controls work from either side." } },
            { "gse_w016", new[] { "枪管回转闭锁的 10 毫米半自动手枪。钢制套筒顶部圆润，聚合物套筒座向前收窄，外露击锤下方连接弧形握把，套筒两侧设低矮拨片。", "A rotating-barrel 10 mm semi-automatic pistol. The steel slide has a rounded top, the polymer frame tapers toward the muzzle, a curved grip sits beneath the exposed hammer, and low-profile levers flank the slide." } },
            { "gse_w017", new[] { "栓动式 7.62 毫米精确步枪。棕色合成枪托表面带深色斑点，宽护木与近乎直立的握把相连，贴腮板独立抬起，盒式弹匣从枪身下方突出。", "A bolt-action 7.62 mm precision rifle. Dark flecks mark the brown synthetic stock, a broad forend joins an almost vertical grip, the cheekpiece is separately raised, and a box magazine projects below the body." } },
            { "gse_w018", new[] { "直拉式 7.62 毫米狩猎步枪。合成枪托带宽大的拇指孔，握把与护木嵌有深色防滑面，枪机柄紧靠扳机上方，细长枪管从短机匣前端伸出。", "A straight-pull 7.62 mm hunting rifle. A synthetic thumbhole stock has dark gripping inserts on the grip and forend, the bolt handle sits just above the trigger, and a slender barrel extends from the short receiver." } },
            { "gse_w021", new[] { "惯性式 12 号半自动猎用霰弹枪。机匣后上缘方正隆起，胡桃木枪托和护木表面明亮，长枪管上方带通风瞄准肋，圆滑握把保留传统猎枪轮廓。", "An inertia-operated 12-gauge semi-automatic hunting shotgun. The receiver rises into a square rear shoulder, glossy walnut forms the stock and forend, a ventilated rib follows the long barrel, and the rounded grip has a traditional sporting profile." } },
            { "gse_w022", new[] { "导气式 7.62 毫米半自动猎枪。银色合金机匣侧面刻有花纹，胡桃木枪托与修长护木前后衔接，深色枪管上方轮廓平直，弹匣底板接近枪身下缘。", "A gas-operated 7.62 mm semi-automatic hunting rifle. Engraving marks the silver alloy receiver between a walnut stock and slender forend, the dark barrel has a straight upper profile, and the magazine floorplate sits near the lower body line." } },
            { "gse_w023", new[] { "自由枪机的 .22 口径运动手枪。细长重型枪管上方有瞄准导轨，木质握把带指槽，枪机后部露出横向抓握面，前端准星内嵌彩色导光条。", "A blowback .22 sporting pistol. A sight rail runs above the long, heavy barrel, wooden grips have finger grooves, the bolt rear has projecting grasping surfaces, and the front sight contains a coloured fibre-optic insert." } },
            { "gse_w025", new[] { "自由枪机的 10 毫米卡宾枪。铝合金上机匣细长平直，透明直弹匣位于握把前方，短护木侧面有散热孔，金属框架枪托只保留细杆与托底。", "A blowback 10 mm carbine. The aluminium upper is long and straight, a transparent stick magazine sits ahead of the grip, the short handguard has side vents, and the metal-frame stock consists of slender supports and a buttplate." } },
            { "gse_w026", new[] { "枪管回转闭锁、闭膛待击的 10 毫米微型冲锋枪。全枪只比手枪略大，弹匣插在握把内，枪管下方带前握把，枪托折叠后贴在右侧。", "A rotating-barrel, closed-bolt 10 mm micro submachine gun, only a little larger than a pistol. The magazine seats in the grip, a front grip hangs under the barrel, and the stock folds along the right side." } },
            { "gse_w027", new[] { "滚柱延迟反冲的 10 毫米冲锋枪。圆筒形螺旋弹仓横卧机匣顶部，枪身下方留有抛壳口，前握把与后方握把分离，细长枪托采用金属支架。", "A roller-delayed blowback 10 mm submachine gun. A cylindrical helical magazine lies along the receiver top, with an ejection port underneath, separate front and rear grips, and a slender metal-frame stock." } },
            { "gse_w028", new[] { "栓动式 7.62 毫米狙击步枪。长枪管穿过圆筒护套，机匣前下方设提把，伸缩枪托由细杆连接宽托底，后方单脚架与前部两脚架相对布置。", "A bolt-action 7.62 mm sniper rifle. A long barrel passes through a cylindrical shroud, a carrying handle sits below the receiver front, and slender rods join the telescopic stock to a broad buttpad between a rear monopod and front bipod." } },
            { "gse_w029", new[] { "杠杆式 12 号霰弹枪。弧面钢机匣接短木握把，枪身没有肩托，大型杠杆环位于扳机下方，枪管与下方管式弹仓平行，短护木覆盖弹仓后段。", "A lever-action 12-gauge shotgun. A curved steel receiver joins a short wooden grip without a shoulder stock, a large lever loop lies below the trigger, and a short forend covers the rear of the tubular magazine beneath the barrel." } },
            { "gse_w030", new[] { "折开式单发 .22 步枪。钢制枪管与细杆骨架枪托组成简洁轮廓，外露击锤位于机匣后方，枪托侧面带备用弹收纳架，枪管根部有折叠铰链。", "A break-action single-shot .22 rifle. A steel barrel and thin-rod skeleton stock form a sparse outline, with an exposed hammer behind the receiver, a cartridge holder on the stock and a folding hinge at the barrel base." } },
            { "gse_w031", new[] { "低枪管轴线的 .45 口径左轮。枪管对应转轮最下方的弹巢，转轮外缘削成平面，长枪管外壳带通风开孔，顶部瞄准线明显高于枪管。", "A low-bore-axis .45 revolver. The barrel aligns with the lowest chamber, the cylinder has flat outer faces, and the long barrel shroud has ventilation openings; the sight line sits noticeably above the bore." } },
            { "gse_w032", new[] { "垂直滑动枪闩的 7.62 毫米单发步枪。钢制机匣表面有彩色淬火纹，右侧外露击锤，扳机护圈与下方杠杆连成整体，短木护木配直握把枪托。", "A falling-block 7.62 mm single-shot rifle. Colour-case-hardening patterns mark the steel receiver, an external hammer sits on the right, the trigger guard forms part of the lower lever, and a short wooden forend pairs with a straight-grip stock." } },
            { "gse_w033", new[] { "双动 .45 口径左轮。枪管上方有一条开孔的通风肋，下方是通到枪口的全长护筒，不锈钢表面打磨光亮，枪身沉重。", "A double-action .45 revolver. A ventilated rib runs along the top of the barrel and a full-length lug along the bottom, the stainless steel is polished bright, and the gun is heavy." } },
            { "gse_w034", new[] { "自由枪机的 10 毫米冲锋手枪。小型钢制机匣下接木质握把，弧形弹匣位于扳机前方，两侧设圆钮状拉机柄，折叠钢丝枪托贴着机匣顶部。", "A blowback 10 mm machine pistol. A small steel receiver sits above a wooden grip, a curved magazine lies ahead of the trigger, round cocking knobs project on both sides, and a folding wire stock rests over the receiver." } },
            { "gse_w036", new[] { "短行程活塞导气的 5.56 毫米卡宾枪。铝合金上机匣搭配聚合物下机匣，护木侧面分布长条开孔，枪托带有侧折铰链和镂空支架。", "A short-stroke gas-piston 5.56 mm carbine. An aluminium upper receiver sits above a polymer lower, with elongated handguard openings and an open-frame stock on a side-folding hinge." } },
            { "gse_w037", new[] { "外露击锤的 10 毫米全尺寸手枪。深色套筒上密布斜向防滑槽，聚合物握把前后覆盖粗纹，扳机护圈前缘平直，套筒座下方设长附件导轨。", "A full-size 10 mm pistol with an external hammer. Close-set diagonal serrations cover the dark slide, coarse texture marks the front and rear of the polymer grip, and a flat-fronted trigger guard sits behind a long accessory rail." } },
            { "gse_w038", new[] { "自由枪机的 10 毫米卡宾枪。聚合物机匣棱角分明，长护木上分布矩形开槽，弧形弹匣紧靠扳机护圈，侧折枪托中部镂空，前端枪管较长。", "A blowback 10 mm carbine. An angular polymer receiver joins a long handguard with rectangular slots, a curved magazine sits close to the trigger guard, and a side-folding stock has an open centre behind the long barrel." } },
            { "gse_w040", new[] { "导气管直吹、枪机旋转闭锁的 5.56 毫米卡宾枪。铝合金上下机匣由两根销钉连接，细长的开槽护木几乎通到枪口，枪托可以伸缩。", "A direct-impingement, rotating-bolt 5.56 mm carbine. Upper and lower aluminium receivers join at two pins, a slim slotted handguard runs almost to the muzzle, and the stock telescopes." } },
            { "gse_w041", new[] { "击针击发的 10 毫米手枪。低矮套筒配铝合金框架，平直扳机位于方形护圈内，枪管下方的前端外壳明显加深，细长握把接近直立。", "A striker-fired 10 mm pistol. A low slide sits on an aluminium frame, a straight trigger occupies a square guard, the front housing extends noticeably below the barrel, and the slender grip is nearly upright." } },
            { "gse_w042", new[] { "栓动式 7.62 毫米无托狙击步枪。弹匣和枪机柄集中在握把后方，聚合物外壳后部宽厚，短开槽护木紧贴前端，顶部导轨沿机匣连续延伸。", "A bolt-action 7.62 mm bullpup sniper rifle. The magazine and bolt handle sit behind the grip, the polymer shell broadens at the rear, a short slotted handguard hugs the front, and a continuous rail runs over the receiver." } },
            { "gse_w044", new[] { "12 号泵动霰弹枪。短枪管前端带多孔枪口装置，长导轨横跨机匣与护木，斜纹前护木配独立握把，镂空聚合物枪托通过侧折铰链连接。", "A 12-gauge pump-action shotgun. A perforated muzzle device caps the short barrel, a long rail spans the receiver and forend, and a grooved pump grip pairs with a separate pistol grip and a side-folding open polymer stock." } },
            { "gse_w045", new[] { "杠杆延迟反冲的 5.56 毫米无托步枪。高提把架在机匣上方，瞄具位于提把内侧，弹匣处于握把后方，宽大的扳机护圈一直延伸到握把底部。", "A lever-delayed blowback 5.56 mm bullpup rifle. A tall carrying handle encloses the sights above the receiver, the magazine sits behind the grip, and the broad trigger guard reaches the grip base." } },
            { "gse_w046", new[] { "外露击锤的 10 毫米大型手枪。长套筒搭配宽厚聚合物套筒座，枪管下方外壳呈方盒状，扳机护圈较小，握把前缘与框架之间留有明显凹口。", "A large 10 mm pistol with an external hammer. A long slide sits on a broad polymer frame with a box-shaped housing beneath the barrel, a small trigger guard, and a pronounced recess where the grip front meets the frame." } },
            { "gse_w047", new[] { "短行程活塞导气的 7.62 毫米轻机枪。沙色机匣顶部导轨连续平直，侧面布置弹链供弹口，开孔护木较长，折叠枪托与短握把分开排列。", "A short-stroke gas-piston 7.62 mm light machine gun. A continuous straight rail tops the tan receiver, the belt-feed opening sits on its side, the vented handguard is long, and the folding stock is separate from the short grip." } },
            { "gse_w048", new[] { "导气式 5.56 毫米无托步枪。聚合物外壳宽厚圆润，握把与护圈连为一体，弹匣位于枪身后部，前抛壳导管沿枪管一侧延伸。", "A gas-operated 5.56 mm bullpup rifle. Its broad, rounded polymer shell joins the grip and trigger guard, with the magazine at the rear and a forward-ejection tube running beside the barrel." } },
            { "gse_w049", new[] { "短行程活塞导气的 7.62 毫米战斗步枪。钢制机匣狭长，枪管上方布置导气管，长护木前端露出调节环，直形弹匣与独立握把前后排列。", "A short-stroke gas-piston 7.62 mm battle rifle. The steel receiver is slender, a gas tube runs above the barrel, an adjustment ring shows at the front of the long handguard, and a straight magazine sits ahead of the separate grip." } },
            { "gse_w050", new[] { "聚合物套筒座的 10 毫米半自动手枪。高套筒外缘棱角分明，握把前后较宽，扳机前方布置双侧保险，枪管下方设导轨，整体表面为深色涂层。", "A 10 mm semi-automatic pistol with a polymer frame. The tall slide has angular edges, the grip is deep from front to rear, ambidextrous safety levers sit ahead of the trigger, and a rail lies below the barrel; the finish is dark throughout." } },
            { "gse_w051", new[] { "长行程活塞导气的 5.56 毫米突击步枪。钢板冲压的上机匣配铝合金下机匣，塑料护木短而粗，管状枪托可以向右折叠。", "A long-stroke gas-piston 5.56 mm assault rifle. A stamped-steel upper receiver sits on an aluminium lower, the plastic handguard is short and thick, and the tubular stock folds to the right." } },
            { "gse_w052", new[] { "枪管短后坐、弹链供弹的 12.7 毫米重机枪。方形钢制机匣连接长重枪管，枪管根部有开孔护套，后端双握把之间设拇指扳机，下方带枪架接口。", "A short-recoil, belt-fed 12.7 mm heavy machine gun. A square steel receiver joins a long heavy barrel with a perforated shroud at its base, twin rear grips flank a thumb trigger, and a mount interface sits underneath." } },
            { "gse_w053", new[] { "长行程活塞导气的 7.62 毫米通用机枪。铆接钢制机匣宽厚，枪管上方设折叠提把，下方导气筒与枪管平行，前置两脚架和聚合物枪托分列两端。", "A long-stroke gas-piston 7.62 mm general-purpose machine gun. A broad riveted steel receiver carries a folding handle above the barrel, a gas cylinder runs parallel below it, and a front bipod and rear polymer stock sit at opposite ends." } },
            { "gse_w054", new[] { "长行程活塞导气的 5.56 毫米轻机枪。弹链供弹盖位于机匣顶部，枪管侧上方设提把，护木带附件导轨，伸缩枪托配宽贴腮板，前端装两脚架。", "A long-stroke gas-piston 5.56 mm light machine gun. A belt-feed cover tops the receiver, a carrying handle rises beside the barrel, rails line the handguard, and a telescopic stock has a broad cheekpiece behind a front bipod." } },
            { "gse_w055", new[] { "自由枪机、无托结构的 10 毫米个人防卫武器。半透明长弹匣沿枪身顶部水平安放，向下抛壳，聚合物枪身把握把和拇指孔做成一体。", "A blowback, bullpup 10 mm personal defence weapon. A translucent long magazine lies horizontally along the top of the gun, cases eject downward, and the polymer body moulds the grip and thumbhole in one piece." } },
            { "gse_w056", new[] { "短行程活塞导气的 5.56 毫米突击步枪。铝合金上机匣平直宽厚，短护木四周设有导轨，侧折伸缩枪托带抬高的贴腮板，枪管外露段较短。", "A short-stroke gas-piston 5.56 mm assault rifle. The broad aluminium upper has a straight profile, rails surround the short handguard, the folding telescopic stock carries a raised cheekpiece, and little of the barrel is exposed." } },
            { "gse_w058", new[] { "击针击发的 10 毫米紧凑型手枪。聚合物套筒座搭配方正钢制套筒，枪身没有外露击锤，扳机中央设联动保险片，握把前缘平直，表面带颗粒纹。", "A striker-fired 10 mm compact pistol. A polymer frame meets a square steel slide, with no external hammer, a central trigger safety blade, and a straight-fronted grip covered in stippled texture." } },
            { "gse_w059", new[] { "滚柱延迟反冲的 10 毫米冲锋枪。聚合物下机匣配铝合金上机匣，半透明长弹匣插在扳机前方，顶部和护木上都有导轨。", "A roller-delayed blowback 10 mm submachine gun. A polymer lower with an aluminium upper, a translucent magazine ahead of the trigger, and mounting rails on top and along the handguard." } },
            { "gse_w060", new[] { "自由枪机的 .22 半自动求生步枪。细长枪管连接小型机匣，黑色聚合物枪托宽厚，内部设有部件收纳空间，短弹匣几乎藏在机匣下方。", "A blowback .22 semi-automatic survival rifle. A slender barrel joins a small receiver, the broad black polymer stock contains storage space for components, and a short magazine barely projects below the action." } },
            { "gse_w061", new[] { ".45 口径杠杆步枪。黄铜机匣搭配胡桃木枪托与短护木，八角形枪管下方并行管式弹仓，外露击锤位于后上方，椭圆杠杆环包围扳机。", "A .45 lever-action rifle. A brass receiver meets a walnut stock and short forend, a tubular magazine runs below the octagonal barrel, an exposed hammer sits at the rear, and an oval lever loop surrounds the trigger." } },
            { "gse_w062", new[] { "导气式 12 号无托霰弹枪。深色外壳包住后部机匣与弹仓，握把位于枪身前半段，顶部一体提把形成长孔，尾部弧形托底与宽厚枪身相接。", "A gas-operated 12-gauge bullpup shotgun. A dark shell encloses the rear action and magazine, the grip sits in the forward half, an integral top handle forms an elongated opening, and a curved buttplate joins the broad body." } },
            { "gse_w063", new[] { "短行程活塞导气的 5.56 毫米突击步枪。机匣和提把由玻纤增强聚合物制成，提把内置光学瞄具，半透明弹匣能看到余弹，镂空枪托可以侧折。", "A short-stroke gas-piston 5.56 mm assault rifle. Receiver and carrying handle are glass-reinforced polymer with an optic built into the handle, translucent magazines show the rounds left, and the skeleton stock folds to the side." } },
            { "gse_w064", new[] { "长行程活塞导气的 7.62 毫米通用机枪。沙色机匣设宽大的顶部供弹盖，粗枪管上方带提把，护木有成排散热孔，后方枪托配抬高的贴腮板。", "A long-stroke gas-piston 7.62 mm general-purpose machine gun. The tan receiver has a broad top feed cover, a handle sits above the heavy barrel, rows of vents pierce the handguard, and the rear stock carries a raised cheekpiece." } },
            { "gse_w065", new[] { "滚柱延迟反冲、闭膛待击的 10 毫米冲锋枪。钢板冲压机匣接弧形弹匣，拉机柄位于护木左上方的长管内，准星带圆形护圈，后照门呈圆筒状。", "A closed-bolt, roller-delayed blowback 10 mm submachine gun. The stamped-steel receiver takes a curved magazine, the charging handle sits in a tube above the handguard on the left, and a hooded front sight pairs with a drum rear sight." } },
            { "gse_w066", new[] { "短行程活塞导气的 10 毫米个人防卫武器。弹匣容纳于握把内，聚合物枪身窄而高，折叠前握把位于短枪管下方，伸缩枪托沿机匣两侧延伸。", "A short-stroke gas-piston 10 mm personal defence weapon. The magazine sits inside the grip of a narrow, tall polymer body, a folding foregrip lies beneath the short barrel, and the telescopic stock runs along both receiver sides." } },
            { "gse_w067", new[] { "闭膛待击、自由枪机的 10 毫米冲锋枪。聚合物机匣外形方正，护木侧面排列长形散热孔，镂空枪托带侧折铰链，弹匣位于独立握把前方。", "A closed-bolt, blowback 10 mm submachine gun. Its boxy polymer receiver has elongated handguard vents, an open-frame stock with a side-folding hinge, and a magazine ahead of the separate grip." } },
            { "gse_w068", new[] { "外露击锤的 10 毫米制式手枪。钢制套筒宽厚，后段有斜向防滑槽，聚合物握把表面布满细纹，方形护圈内侧宽敞，前方导轨与套筒座连为一体。", "A 10 mm service pistol with an external hammer. The broad steel slide has rear diagonal serrations, fine texture covers the polymer grip, and a roomy square trigger guard sits behind a rail integral to the frame." } },
            { "gse_w069", new[] { "单发式 40 毫米榴弹发射器。粗短发射管带横向防滑纹，上方装有翻折标尺瞄具，聚合物握把与伸缩肩托分开布置，侧面铰链位于管体后缘。", "A single-shot 40 mm grenade launcher. The short, thick launch tube has transverse grip ribs, a folding ladder sight sits above it, the polymer grip and telescopic stock are separate, and a side hinge lies at the tube rear." } },
            { "gse_w070", new[] { "短行程活塞导气的 5.56 毫米突击步枪。铝合金上机匣顶部是整根导轨，操作件左右对称，枪托可伸缩也可侧折。", "A short-stroke gas-piston 5.56 mm assault rifle. One long rail tops the aluminium upper receiver, the controls are mirrored on both sides, and the stock both telescopes and folds." } },
            { "gse_w071", new[] { "短行程活塞导气的 5.56 毫米卡宾枪。胡桃木枪托和短护木围住机匣，细长枪管大半外露，直形盒式弹匣位于扳机前方，整体轮廓窄长。", "A short-stroke gas-piston 5.56 mm carbine. A walnut stock and short handguard surround the receiver, most of the slim barrel remains exposed, and a straight box magazine sits ahead of the trigger in a narrow overall profile." } },
            { "gse_w073", new[] { "导气式 12 号无托霰弹枪。宽厚聚合物枪身内排列三根旋转管式弹仓，握把前缘带大护圈，短护木侧面布有斜向开孔，顶部导轨平直连续。", "A gas-operated 12-gauge bullpup shotgun. Three rotating magazine tubes occupy the broad polymer body, a large guard fronts the grip, diagonal vents line the short handguard, and a continuous straight rail runs along the top." } },
            { "gse_w074", new[] { "套筒式枪机的 10 毫米紧凑冲锋枪。枪机包覆枪管后段，弹匣位于握把内，方形钢制上机匣配聚合物下机匣，短前握把上方设有侧面导轨。", "A telescoping-bolt 10 mm compact submachine gun. The bolt surrounds the rear of the barrel, the magazine sits inside the grip, and a square steel upper joins a polymer lower with side rails above the short foregrip." } },
            { "gse_w075", new[] { "长行程活塞导气、无托结构的 5.56 毫米步枪。聚合物枪身短而厚，顶部是平直的长导轨，弹匣插在握把后方，前方只留一截短护木。", "A long-stroke gas-piston 5.56 mm bullpup rifle. The polymer body is short and thick with a long flat rail on top, the magazine seats behind the grip, and only a short handguard is left in front." } },
            { "gse_w076", new[] { "自由枪机的 .22 口径手枪。细长上机匣顶部铺满导轨，开槽护木围住枪管，透明弹匣容纳于长握把内，后端拉机柄呈横向伸出的耳状。", "A blowback .22 pistol. A rail covers the long upper receiver, a slotted handguard surrounds the barrel, a transparent magazine sits inside the long grip, and the rear charging handle has projecting side ears." } },
            { "gse_w077", new[] { "自由枪机的 10 毫米大型手枪。水平长弹匣位于枪管下方，握把与扳机集中在后部，细长机匣侧面有成排圆孔，顶部导轨几乎贯穿全长。", "A large blowback 10 mm pistol. A long horizontal magazine sits below the barrel, the grip and trigger cluster at the rear, round openings line the slender receiver, and a top rail runs almost its full length." } },
            { "gse_w078", new[] { "泵动式 12 号无托霰弹枪。单根管式弹仓沿枪管下方布置，黑色聚合物枪身窄长，顶部为平直导轨，前护木表面带横纹，抛壳口位于枪身下方。", "A pump-action 12-gauge bullpup shotgun. A single magazine tube runs beneath the barrel, the black polymer body is narrow, a straight rail tops it, transverse ribs cover the forend, and the ejection port faces downward." } },
            { "gse_w079", new[] { "短行程活塞导气的 7.62 毫米无托步枪。钢制机匣外覆聚合物，弹匣位于握把后方，前抛壳导管沿枪管上方布置，短护木与厚实托底形成紧凑外形。", "A short-stroke gas-piston 7.62 mm bullpup rifle. Polymer covers the steel receiver, the magazine sits behind the grip, and a forward-ejection tube runs above the barrel; a short handguard and thick buttpad define the compact profile." } },
            { "gse_w080", new[] { "长行程活塞导气的 5.56 毫米轻型步枪。聚合物枪身配细长钢枪管，枪托底部有折叠铰链，备用弹匣收纳在托内，分瓣护木兼作两脚架。", "A long-stroke gas-piston 5.56 mm light rifle. The polymer body surrounds a slender steel barrel; the stock has a lower folding hinge and spare-magazine storage, while the split handguard doubles as a bipod." } },
            { "gse_w081", new[] { "自由枪机的 10 毫米折叠卡宾枪。圆管状机匣向后延伸至托底，弹匣位于握把内，长护木表面密布开槽，枪管根部的铰链构成明显分界。", "A blowback 10 mm folding carbine. The tubular receiver extends rearward to the buttplate, the magazine sits inside the grip, slots cover the long handguard, and a hinge at the barrel base forms a distinct dividing line." } },
            { "gse_w082", new[] { "延迟反冲式 .45 口径冲锋枪。枪管轴线很低，枪机下方的滑块容纳在向下凸出的机匣内，弹匣紧邻扳机护圈，枪身前部高而宽厚。", "A delayed-blowback .45 submachine gun. The barrel axis sits very low, a slider below the bolt occupies the downward-projecting receiver, and the magazine lies close to the trigger guard beneath a tall, bulky front section." } },
            { "gse_w083", new[] { "气体延迟反冲的 10 毫米竞赛手枪。枪管位置很低，固定的顶部瞄准座与两侧套筒分开，金属握把后缘向上伸出，枪身前部密布斜向开槽。", "A gas-delayed blowback 10 mm competition pistol. The barrel sits very low, the fixed upper sight mount is separate from the slide sides, the metal grip extends upward at the rear, and diagonal cuts cover the front section." } },
            { "gse_w084", new[] { "栓动式 7.62 毫米军用步枪。木质护木几乎包至枪口，前端金属鼻帽围住准星根部，弧形盒式弹匣向下突出，短枪机柄紧靠扳机上方。", "A bolt-action 7.62 mm service rifle. Wooden furniture reaches almost to the muzzle, a metal nose cap surrounds the front-sight base, a curved box magazine projects below, and a short bolt handle sits just above the trigger." } },
            { "gse_w086", new[] { "单发式 40 毫米榴弹发射器。圆筒形枪管下包带横纹的护罩，独立握把连接金属支架，伸缩肩托位于后方，上部标尺瞄具高出管体。", "A single-shot 40 mm grenade launcher. A transversely ribbed guard encloses the lower cylindrical barrel, a separate grip joins the metal frame, a telescopic stock sits at the rear, and an elevated ladder sight stands above the tube." } },
            { "gse_w087", new[] { "长行程活塞导气的 7.62 毫米半自动步枪。胡桃木枪托延伸至长护木，机匣顶部敞开，内置弹仓采用漏夹供弹，枪管下方可见导气筒。", "A long-stroke gas-piston 7.62 mm semi-automatic rifle. The walnut stock extends into a long forend, the receiver is open at the top, an internal magazine uses an en-bloc clip, and a gas cylinder lies below the barrel." } },
            { "gse_w088", new[] { "导气式、旋转枪机闭锁的 .45 口径重型手枪。固定枪管外形粗大，套筒后部带斜向防滑槽，钢制框架配宽握把，明亮金属表面与黑色握把片分界清楚。", "A gas-operated, rotating-bolt heavy .45 pistol. A bulky fixed barrel leads to a slide with rear diagonal serrations; the steel frame has a broad grip, and the bright metal finish contrasts with black grip panels." } },
            { "gse_w089", new[] { "7.62 毫米杠杆步枪。抛光不锈钢机匣配灰色层压木枪托，杠杆环宽大，顶部导轨一直伸向护木，枪管与管式弹仓上下平行排列。", "A 7.62 mm lever-action rifle. A polished stainless-steel receiver meets a grey laminated stock, the lever loop is oversized, a top rail reaches toward the forend, and the barrel runs parallel above a tubular magazine." } },
            { "gse_w090", new[] { "栓动式 7.62 毫米猎枪。层压木枪托带大型拇指孔，宽护木沿枪管下方延伸，圆球状枪机柄位于右侧，黑色托底与层状木纹形成清晰分界。", "A bolt-action 7.62 mm hunting rifle. A laminated thumbhole stock has a broad forend beneath the barrel, a round bolt knob sits on the right, and a black buttpad forms a clear boundary with the layered wood grain." } },
            { "gse_w091", new[] { "枪管短后坐的 7.62 毫米通用机枪。冲压钢制枪管护套侧面排列长形开孔，前端带粗大的枪口装置，机匣采用弹链供弹，木质枪托向后收窄。", "A short-recoil 7.62 mm general-purpose machine gun. Elongated openings line the stamped-steel barrel shroud, a bulky muzzle device caps the front, the receiver is belt-fed, and the wooden stock narrows toward the rear." } },
            { "gse_w092", new[] { "栓动式 7.62 毫米军用步枪。细长木枪托配钢制机匣，内置弹仓底部突出，枪管护木由金属箍固定，枪机柄向下弯曲，整体保留狭长的步兵步枪轮廓。", "A bolt-action 7.62 mm service rifle. A slender wooden stock holds a steel receiver, the internal magazine projects underneath, metal bands secure the barrel furniture, and the bolt handle bends downward; the infantry-rifle profile is long and narrow." } },
            { "gse_w093", new[] { "12 号短管泵动霰弹枪。弯曲的聚合物后握把没有肩托，前护木密布横向凹槽并带手带，枪管与下方弹仓前端接近齐平，整枪轮廓短而低。", "A short-barrelled 12-gauge pump-action shotgun. A curved polymer rear grip has no shoulder stock, transverse grooves and a hand strap mark the forend, and the barrel and magazine end almost together in a short, low profile." } },
            { "gse_w094", new[] { "单动式 .22 口径迷你左轮。小型不锈钢框架配木质握把片，转轮与外露击锤占据枪身大部，短扳机直接伸出框架，周围没有扳机护圈。", "A single-action .22 mini revolver. Wooden grip panels meet a small stainless-steel frame dominated by its cylinder and exposed hammer; a short trigger projects directly from the frame without a trigger guard." } },
            { "gse_w095", new[] { "自由枪机的 .22 口径比赛手枪。贴合手形的木质握把带宽托掌，弹匣位于扳机前方，枪管外包长方形配重护罩，低矮准星与后照门前后分列。", "A blowback .22 match pistol. An anatomical wooden grip has a broad palm shelf, the magazine sits ahead of the trigger, and a rectangular weight housing surrounds the barrel between a low front sight and rear sight." } },
            { "gse_w096", new[] { "7.62 毫米燧发长枪。细长木枪托沿八角形枪管延伸，右侧燧发锁外露，黄铜护圈与弯曲托底表面明亮，枪管下方平行收纳一根通条。", "A 7.62 mm flintlock long rifle. A slender wooden stock follows the octagonal barrel, the flintlock is exposed on the right, bright brass forms the guard and curved buttplate, and a ramrod lies parallel below the barrel." } },
            { "gse_w097", new[] { "栓动式 12.7 毫米反器材步枪。长枪管配大型制退器，钢制机匣架在铝合金底盘上，提把位于枪身中部，前方两脚架与托底单脚架构成支撑。", "A bolt-action 12.7 mm anti-materiel rifle. A long barrel carries a large muzzle brake, the steel receiver rests on an aluminium chassis, and a central carrying handle sits between the front bipod and rear monopod supports." } },
            { "gse_w098", new[] { "开膛待击、自由枪机的 10 毫米冲锋枪。冲压钢机匣嵌在木质枪托内，枪管护套布满散热孔，前端呈斜切形，下方弹鼓使枪身中段明显加宽。", "An open-bolt, blowback 10 mm submachine gun. A stamped-steel receiver sits in a wooden stock, a perforated barrel shroud ends in an angled face, and the drum magazine broadens the middle of the gun." } },
            { "gse_w099", new[] { "栓动式 7.62 毫米轻型步枪。浅色金属机匣配细长开槽护木，弹匣位于独立握把前方，骨架枪托轮廓纤细，蓝色连接件点缀在枪托两端。", "A light bolt-action 7.62 mm rifle. A pale metal receiver joins a slender slotted handguard, the magazine sits ahead of the separate grip, and a slim skeleton stock has blue fittings at either end." } },
            { "gse_w100", new[] { "转轮供弹的 12 号卡宾枪。木质长枪托连接钢制框架，转轮两侧设有挡气护片，长枪管下方带短护木，外露击锤位于转轮后方。", "A cylinder-fed 12-gauge carbine. A full wooden stock meets a steel frame, shields flank the cylinder, a short forend sits beneath the long barrel, and an exposed hammer stands behind the cylinder." } },
            { "gse_w101", new[] { "自由枪机的 .22 半自动步枪。胡桃木枪托搭配铝合金机匣，短护木前端围着金属箍，旋转式弹匣嵌在枪身下方，底部与枪托轮廓基本齐平。", "A blowback .22 semi-automatic rifle. A walnut stock holds an aluminium receiver, a metal band encircles the short forend, and a rotary magazine fits almost flush with the underside of the stock." } },
            { "gse_w102", new[] { "自由枪机的 .22 口径靶用手枪。粗圆枪管与管状机匣连成直线，枪机后端左右突出，握把明显向后倾斜，顶端设可调后照门，外观细长。", "A blowback .22 target pistol. A thick round barrel aligns with the tubular receiver, the bolt rear projects to both sides, and the grip leans sharply rearward; an adjustable rear sight tops the slender overall profile." } },
            { "gse_w103", new[] { "导气式 5.56 毫米半自动步枪。硬木枪托搭配深色钢制机匣，枪管上方盖着短护罩，右侧导杆与拉机柄外露，盒式弹匣位于扳机前方。", "A gas-operated 5.56 mm semi-automatic rifle. A hardwood stock holds a dark steel receiver, a short guard covers the top of the barrel, and the operating rod and handle are exposed on the right above a box magazine ahead of the trigger." } },
            { "gse_w104", new[] { "自由枪机的 10 毫米卡宾枪。黑色合成枪托采用传统猎枪轮廓，短弹匣位于扳机前方，枪管带纵向凹槽，机匣与护木之间有明显的分体接缝。", "A blowback 10 mm carbine. A black synthetic stock has a traditional sporting profile, a short magazine sits ahead of the trigger, lengthwise flutes mark the barrel, and a distinct joint separates receiver and forend." } },
            { "gse_w105", new[] { "栓动式 7.62 毫米精确步枪。青铜色金属底盘连接长开槽护木，枪托与枪管大致同轴，镂空托架带可调贴腮板，独立握把后方留有较大空隙。", "A bolt-action 7.62 mm precision rifle. A bronze-coloured metal chassis joins a long slotted handguard, the stock lies roughly in line with the barrel, an open frame carries an adjustable cheekpiece, and a broad gap lies behind the separate grip." } },
            { "gse_w106", new[] { "上下双管的 12 号猎用霰弹枪。深色金属机匣搭配胡桃木枪托，窄护木包住下管，顶部通风瞄准肋沿枪管延伸，单扳机位于椭圆形护圈内。", "A 12-gauge over-under hunting shotgun. A dark metal receiver joins a walnut stock, a narrow forend encloses the lower barrel, a ventilated rib runs along the top, and a single trigger sits inside an oval guard." } },
            { "gse_w107", new[] { "双动式 .45 口径重型左轮。钢制枪管护筒带成排通风孔，转轮表面有长条减重槽，黑色握把嵌着木质侧片，顶部后照门独立突出。", "A double-action heavy .45 revolver. Rows of vents pierce the steel barrel shroud, long flutes run along the cylinder, wooden panels inset the black grip, and a separate rear sight projects above the frame." } },
            { "gse_w108", new[] { "栓动式 7.62 毫米狙击步枪。黑色金属底盘配长开孔护木，枪托中段镂空，宽贴腮板独立悬置于上方，粗枪机柄伸向握把，弹匣口与护圈紧邻。", "A bolt-action 7.62 mm sniper rifle. A black metal chassis has a long vented handguard, an open-centred stock with a broad separate cheekpiece above it, a thick bolt handle reaching toward the grip, and a magazine well beside the trigger guard." } },
            { "gse_w109", new[] { "栓动式 7.62 毫米猎枪。带拇指孔的木枪托纹理连续，纤细护木包住枪管后段下方，机匣表面深暗平滑，枪机柄末端为较大的圆形握球。", "A bolt-action 7.62 mm hunting rifle. Grain flows along the wooden thumbhole stock, a slim forend encloses the lower rear barrel, the receiver has a smooth dark finish, and the bolt handle ends in a large rounded knob." } },
            { "gse_w110", new[] { "短行程活塞导气的 5.56 毫米步枪。铝合金机匣接细长开槽护木，上方导轨连续平直，纤细的金属枪托带侧折铰链，枪身两侧均有操作件。", "A short-stroke gas-piston 5.56 mm rifle. The aluminium receiver joins a slim slotted handguard beneath a continuous straight rail, with a slender side-folding metal stock and controls on both sides." } },
            { "gse_w111", new[] { "长行程活塞导气的 5.56 毫米步枪。钢板冲压机匣搭配聚合物护木，半透明弹匣侧面带连接凸榫，护木下方收纳两脚架，枪托呈镂空框架状。", "A long-stroke gas-piston 5.56 mm rifle. A stamped-steel receiver has a polymer handguard, a translucent magazine with coupling lugs, a bipod stowed beneath the handguard and an open-frame stock." } },
            { "gse_w112", new[] { "泵动式 12 号无托霰弹枪。两根管式弹仓并列在枪管下方，聚合物枪身宽厚方正，顶部导轨较长，前护木带垂直握把，抛壳口位于后部下方。", "A pump-action 12-gauge bullpup shotgun. Two magazine tubes lie side by side below the barrel, the polymer body is broad and angular, a long rail tops it, a vertical grip attaches to the forend, and ejection is underneath the rear." } },
            { "gse_w113", new[] { "长行程活塞导气的 5.56 毫米突击步枪。机匣顶部较平，前端准星带圆形护圈，短聚合物护木表面有散热孔，实心枪托通过侧面铰链连接。", "A long-stroke gas-piston 5.56 mm assault rifle. A relatively flat-topped receiver leads to a ring-protected front sight, with vents in the short polymer handguard and a solid stock joined by a side hinge." } },
            { "gse_w114", new[] { "自由枪机的 10 毫米微声冲锋枪。一体式消音器占据枪身前部，圆筒外表平滑，后方钢制机匣配独立握把，金属伸缩枪托沿两侧收纳。", "A blowback 10 mm suppressed submachine gun. A smooth cylindrical integral suppressor occupies the front, followed by a steel receiver and separate grip; the metal telescopic stock nests along the sides." } },
            { "gse_w115", new[] { "击针击发的 10 毫米模块化手枪。钢制击发组件位于聚合物握把框架内，套筒前后设深防滑槽，尾部稍向外扩，扳机护圈下缘有指位凹槽。", "A striker-fired 10 mm modular pistol. A steel fire-control unit sits inside the polymer grip frame, deep serrations mark both ends of the slide, its rear flares slightly outward, and a finger recess shapes the underside of the trigger guard." } },
            { "gse_w116", new[] { "导气式 5.56 毫米无托步枪。聚合物枪身棱角分明，弹匣位于握把后方，中央拉机柄藏在高架导轨下，枪身两侧各有一处抛壳口盖板。", "A gas-operated 5.56 mm bullpup rifle. Its angular polymer body places the magazine behind the grip and a central charging handle below the raised rail, with an ejection-port cover on each side." } },
            { "gse_w117", new[] { "短行程活塞导气的 7.62 毫米半自动步枪。胡桃木枪托搭配钢制机匣，枪机顶部外露，长盒式弹匣向下突出，枪口装有带纵向开槽的消焰器。", "A short-stroke gas-piston 7.62 mm semi-automatic rifle. A walnut stock holds a steel receiver with an exposed bolt top, a long box magazine projects below, and a flash suppressor with lengthwise slots caps the muzzle." } },
            { "gse_w118", new[] { "滚柱延迟反冲的 12 号半自动霰弹枪。四根弹仓管组成可转动的筒状组件，位于枪管下方，短机匣接直线枪托，顶部与两侧导轨围住前部。", "A roller-delayed blowback 12-gauge semi-automatic shotgun. Four magazine tubes form a rotating cylindrical assembly below the barrel, the short receiver joins a straight stock, and top and side rails surround the front section." } },
            { "gse_w119", new[] { "并列双管的 12 号泵动霰弹枪。两根管式弹仓布置在枪管下方，无托枪身宽厚，前护木带垂直握把，顶部导轨跨过机匣，后部配宽大的托底。", "A twin-barrelled 12-gauge pump-action shotgun. Two magazine tubes sit below the side-by-side barrels, the bullpup body is broad, a vertical grip extends from the forend, and a top rail spans the receiver ahead of a wide buttpad." } },
            { "gse_w120", new[] { "并列双管的 .22 口径左轮。宽厚框架内装大直径转轮，短枪管在前端并排外露，宽扳机带有联动保险片，黑色握把表面分布指槽。", "A .22 revolver with twin side-by-side barrels. A thick frame encloses a broad cylinder, both short barrels show at the front, and a wide trigger carries a safety blade above a black finger-grooved grip." } },
            { "gse_w121", new[] { "开膛待击、自由枪机的 10 毫米冲锋枪。钢管机匣外形平直，弹匣座横置于左侧，短枪管护套留有开孔，枪托由细长金属支架与平直托底组成。", "An open-bolt, blowback 10 mm submachine gun. A straight tubular steel receiver carries a magazine housing on its left, a short perforated barrel shroud, and a stock formed from a narrow metal support and flat buttplate." } },
            { "gse_w122", new[] { "开膛待击、自由枪机的 10 毫米冲锋枪。圆管机匣与开孔枪管护套连成直线，弧形弹匣横置左侧，握把向后倾斜，金属框架枪托带下折铰链。", "An open-bolt, blowback 10 mm submachine gun. The tubular receiver aligns with a perforated barrel shroud, a curved magazine projects from the left, the grip slopes rearward, and the metal-frame stock has an underfolding hinge." } },
            { "gse_w123", new[] { "短行程活塞导气的 5.56 毫米无托步枪。聚合物枪身后部宽厚，半透明弹匣紧靠托底，前握把位于外露枪管下方，扳机护圈与握把底部相连。", "A short-stroke gas-piston 5.56 mm bullpup rifle. The polymer body broadens toward the butt, a translucent magazine sits close to the buttpad, and a foregrip hangs below the exposed barrel; the trigger guard joins the grip base." } },
            { "gse_w124", new[] { "栓动式 12.7 毫米反器材步枪。重型长枪管带多孔制退器，机匣顶部铺设长导轨，盒式弹匣从左侧突出，金属枪托带贴腮板，前方设两脚架。", "A bolt-action 12.7 mm anti-materiel rifle. A heavy barrel has a multi-port muzzle brake, a long rail tops the receiver, a box magazine projects from the left, and a metal stock with cheekpiece sits behind a front bipod." } },
            { "gse_w125", new[] { "低枪管轴线的 10 毫米手枪。套筒较长且上缘倾斜，聚合物握把大幅后倾，前后表面带方格防滑纹，宽护圈与套筒座衔接处留有明显凹槽。", "A low-bore-axis 10 mm pistol. The long slide has sloping upper edges, the polymer grip leans strongly rearward with checkered front and back surfaces, and a pronounced recess marks the junction of the broad guard and frame." } },
            { "gse_w126", new[] { "栓动式 7.62 毫米轻型步枪。合成枪托外形低矮，长导轨向护木前方延伸，折叠两脚架收纳在护木两侧，托底前方另有备用弹匣收纳位。", "A light bolt-action 7.62 mm rifle. The synthetic stock has a low profile, a long rail extends forward over the forend, a folding bipod nests in its sides, and a spare-magazine recess sits ahead of the buttpad." } },
            { "gse_w127", new[] { "栓动式 7.62 毫米狙击步枪。灰色金属底盘配短开孔护木，长枪管大半外露，折叠枪托带厚贴腮板和宽托底，前方两脚架接在护木下缘。", "A bolt-action 7.62 mm sniper rifle. A grey metal chassis has a short vented handguard, most of the long barrel is exposed, the folding stock has a thick cheekpiece and broad buttpad, and a bipod attaches beneath the forend." } },
            { "gse_w128", new[] { "并列双管的 12 号短霰弹枪。深色双枪管与胡桃木枪托形成传统外形，短护木紧贴枪管下方，椭圆护圈内前后排列双扳机，机匣顶部设开锁杆。", "A short 12-gauge side-by-side shotgun. Dark twin barrels and a walnut stock form a traditional outline, a short forend lies beneath the barrels, two triggers line up inside an oval guard, and a top lever sits on the action." } },
            { "gse_w129", new[] { "双动式 .45 口径左轮。轻合金框架搭配深色转轮，直线形枪管护筒上下设有导轨，前端准星独立竖起，橡胶握把表面带细密防滑纹。", "A double-action .45 revolver. A light-alloy frame surrounds a dark cylinder, rails run above and below the straight barrel shroud, a separate front sight stands at the muzzle, and fine texture covers the rubber grip." } },
            { "gse_w130", new[] { "外露击锤的 10 毫米竞赛手枪。长套筒前段开有成排减重孔，钢制框架下缘平直，红色握把片与深色枪身相接，后照门高于套筒表面。", "A 10 mm competition pistol with an external hammer. Rows of lightening cuts pierce the long slide front, the steel frame has a straight lower edge, red grip panels meet the dark body, and the rear sight stands above the slide." } },
            { "gse_w131", new[] { "栓动式 7.62 毫米战术步枪。黑色铝合金底盘配长护木，矩形开槽沿两侧排列，盒式弹匣位于独立握把前方，侧折枪托设有平直贴腮板和宽托底。", "A bolt-action 7.62 mm tactical rifle. A black aluminium chassis joins a long handguard with rectangular side slots, a box magazine sits ahead of the separate grip, and a side-folding stock carries a flat cheekpiece and broad buttpad." } },
            { "gse_w132", new[] { "单动式 .45 口径雕花左轮。钢制框架和转轮覆盖卷草纹，弯曲木握把向底部张开，外露击锤高于框架，侧面装弹门紧邻转轮后缘。", "A single-action engraved .45 revolver. Scrollwork covers the steel frame and cylinder, the curved wooden grip flares at its base, an exposed hammer rises above the frame, and a loading gate borders the cylinder rear." } },
            { "gse_w133", new[] { "长行程活塞导气的 7.62 毫米通用机枪。机匣低矮宽长，顶部设弹链供弹盖，枪管侧上方带提把，短护木下接前握把，两脚架固定在前端支架上。", "A long-stroke gas-piston 7.62 mm general-purpose machine gun. A low, broad receiver has a top belt-feed cover, a handle rises beside the barrel, a foregrip extends below the short handguard, and a front bracket carries the bipod." } },
            { "gse_w134", new[] { "泵动式 12 号无托霰弹枪。两根管式弹仓并列在枪管上方，聚合物外壳高而方正，侧面带观察开口，独立握把位于中段，前护木宽厚。", "A pump-action 12-gauge bullpup shotgun. Two magazine tubes lie side by side above the barrel, the polymer shell is tall and angular with side viewing openings, a separate grip sits centrally, and the forend is broad." } },
            { "gse_w135", new[] { "自由枪机的 .22 口径比赛手枪。蓝色层压木握把带托掌板，弹匣位于扳机前方，枪管前段包着蓝色方形护罩，枪机侧面露出银色金属表面。", "A blowback .22 match pistol. A blue laminated-wood grip has a palm shelf, the magazine sits ahead of the trigger, a blue rectangular shroud encloses the barrel front, and silver metal shows at the side of the bolt." } },
            { "gse_w137", new[] { "击针击发的 10 毫米全尺寸手枪。高而方正的钢制套筒刻有宽深防滑槽，聚合物握把后缘弧度明显，表面覆盖颗粒纹，枪管下方设长段导轨。", "A full-size striker-fired 10 mm pistol. Broad, deep serrations cut into the tall square steel slide, the polymer grip has a pronounced curved backstrap and stippled surface, and a long rail runs below the barrel." } },
            { "gse_w138", new[] { "栓动式 7.62 毫米长程猎枪。黑色合成枪托表面带浅色网纹，贴腮处抬高，长枪管开有纵向凹槽，前端设制退器，枪机表面可见螺旋槽。", "A bolt-action 7.62 mm long-range hunting rifle. Pale webbing marks the black synthetic stock and raised cheekpiece, the long barrel has lengthwise flutes and a muzzle brake, and spiral flutes are visible on the bolt." } },
            { "gse_w139", new[] { "7.62 毫米杠杆步枪。深色钢制机匣配直握把木枪托，短护木前端带金属箍，管式弹仓紧贴枪管下方，外露击锤与窄杠杆环保持传统布局。", "A 7.62 mm lever-action rifle. A dark steel receiver joins a straight-grip wooden stock, a metal band encircles the short forend, and a tubular magazine runs close below the barrel; the exposed hammer and narrow lever loop follow a traditional layout." } },
            { "gse_w140", new[] { "12 号泵动霰弹枪。枪管与管式弹仓呈银灰色，黑色合成枪托接深色机匣，短护木刻有密集横纹，枪口上方设低矮准星，整体面向潮湿环境使用。", "A 12-gauge pump-action shotgun. The barrel and magazine tube are silver-grey, a black synthetic stock joins the dark receiver, close-set ribs cover the short forend, and a low front sight tops a design intended for damp conditions." } },
            { "gse_w141", new[] { "长行程活塞导气的 5.56 毫米步枪。钢制机匣搭配胡桃木枪托，木护木侧面有三道散热缝，机匣前部带加厚凸起，弧形弹匣位于枪身下方。", "A long-stroke gas-piston 5.56 mm rifle. A steel receiver and walnut stock meet a wooden handguard with three side vents; reinforcing bulges mark the receiver front above a curved magazine." } },
        };

